def convert_existing_routine_assignments(apps, schema_editor):
    RutinaAsignada = apps.get_model('princpal', 'RutinaAsignada')
    PlantillaRutina = apps.get_model('princpal', 'PlantillaRutina')
    EjercicioPlantillaRutina = apps.get_model('princpal', 'EjercicioPlantillaRutina')
    EjercicioRutinaAsignada = apps.get_model('princpal', 'EjercicioRutinaAsignada')
    OcurrenciaRutina = apps.get_model('princpal', 'OcurrenciaRutina')
    connection = schema_editor.connection

    with connection.cursor() as cursor:
        tables = {item.name for item in connection.introspection.get_table_list(cursor)}
    legacy_assignment_table = 'princpal_rutinaasignada_legacy_0015'
    legacy_template_table = 'princpal_rutinaplantilla'
    legacy_occurrence_table = 'princpal_rutinaocurrencia'
    has_alternate_schema = legacy_assignment_table in tables
    legacy_assignments = {}
    legacy_templates = {}
    legacy_occurrences = {}
    templates_by_owner = {}

    if has_alternate_schema:
        with connection.cursor() as cursor:
            cursor.execute(
                f'SELECT id, plantilla_id, fecha_inicio, fecha_fin, dias_semana, series, '
                f'repeticiones, duracion_minutos, notas_medico '
                f'FROM {connection.ops.quote_name(legacy_assignment_table)}'
            )
            legacy_assignments = {
                row[0]: {
                    'template_id': row[1],
                    'start': row[2],
                    'end': row[3],
                    'weekdays': row[4],
                    'series': row[5],
                    'repetitions': row[6],
                    'duration': row[7],
                    'notes': row[8],
                }
                for row in cursor.fetchall()
            }
            cursor.execute(
                f'SELECT id, video_id, titulo FROM {connection.ops.quote_name(legacy_template_table)}'
            )
            legacy_templates = {
                row[0]: {'video_id': row[1], 'title': row[2]}
                for row in cursor.fetchall()
            }
            cursor.execute(
                f'SELECT rutina_asignada_id, fecha, completada_en, dolor, dificultad, comentario '
                f'FROM {connection.ops.quote_name(legacy_occurrence_table)}'
            )
            for assignment_id, occurrence_date, completed_at, pain, difficulty, comment in cursor.fetchall():
                legacy_occurrences.setdefault(assignment_id, {})[occurrence_date] = {
                    'completed_at': completed_at,
                    'pain': pain,
                    'difficulty': difficulty,
                    'comment': comment,
                }

        patient_doctors = {
            patient_id: doctor_id
            for patient_id, doctor_id in apps.get_model('princpal', 'Paciente')
            .objects.using(connection.alias)
            .filter(pk__in=[
                assignment.paciente_id
                for assignment in RutinaAsignada.objects.using(connection.alias).all()
            ])
            .values_list('pk', 'doctor_id')
        }
        owners_by_template = {}
        for assignment_id, legacy in legacy_assignments.items():
            assignment = RutinaAsignada.objects.using(connection.alias).get(pk=assignment_id)
            owners_by_template.setdefault(legacy['template_id'], set()).add(
                patient_doctors.get(assignment.paciente_id)
            )
        for old_template_id, old_template in legacy_templates.items():
            owners = owners_by_template.get(old_template_id) or {None}
            for doctor_id in owners:
                template = PlantillaRutina.objects.using(connection.alias).create(
                    doctor_id=doctor_id,
                    nombre=(old_template['title'] or 'Rutina migrada')[:150],
                    descripcion='Plantilla conservada de la versión anterior.',
                )
                templates_by_owner[(old_template_id, doctor_id)] = template
                EjercicioPlantillaRutina.objects.using(connection.alias).create(
                    plantilla_id=template.pk,
                    video_id=old_template['video_id'],
                    titulo=(old_template['title'] or 'Ejercicio migrado')[:150],
                    orden=1,
                )

    for assignment in RutinaAsignada.objects.using(connection.alias).select_related('paciente').iterator():
        legacy = legacy_assignments.get(assignment.pk)
        doctor_id = assignment.paciente.doctor_id
        if legacy:
            template = templates_by_owner.get((legacy['template_id'], doctor_id))
            old_template = legacy_templates.get(legacy['template_id'], {})
            video_id = old_template.get('video_id') or assignment.video_id
            exercise_title = old_template.get('title') or assignment.titulo
            start_date = legacy['start'] or assignment.fecha_programada
            end_date = legacy['end'] or start_date
            weekdays = legacy['weekdays']
            if isinstance(weekdays, str):
                weekdays = json.loads(weekdays)
            weekdays = [int(day) for day in (weekdays or [])]
            if not weekdays:
                weekdays = [start_date.weekday()]
            series = max(int(legacy['series'] or 1), 1)
            repetitions = (legacy['repetitions'] or '').strip()
            duration = legacy['duration'] or None
            if duration is not None:
                duration = max(int(duration), 1)
            notes = legacy['notes'] or ''
            if duration is None and not repetitions:
                repetitions = '10'
        else:
            template = None
            video_id = assignment.video_id
            exercise_title = assignment.titulo
            start_date = assignment.fecha_programada
            end_date = assignment.fecha_programada
            weekdays = [start_date.weekday()]
            series = 3
            repetitions = '10'
            duration = None
            notes = ''

        if template is None:
            template = PlantillaRutina.objects.using(connection.alias).create(
                doctor_id=doctor_id,
                nombre=assignment.titulo,
                descripcion='Plantilla creada automáticamente al migrar una asignación existente.',
            )
            EjercicioPlantillaRutina.objects.using(connection.alias).create(
                plantilla_id=template.pk,
                video_id=video_id,
                titulo=exercise_title[:150],
                orden=1,
            )

        RutinaAsignada.objects.using(connection.alias).filter(pk=assignment.pk).update(
            plantilla_id=template.pk,
            fecha_inicio=start_date,
            fecha_fin=end_date,
            dias_semana=weekdays,
        )
        EjercicioRutinaAsignada.objects.using(connection.alias).create(
            asignacion_id=assignment.pk,
            video_id=video_id,
            titulo=exercise_title[:150],
            orden=1,
            series=series,
            repeticiones=repetitions,
            duracion_minutos=duration,
            notas_medico=notes,
        )

        feedback = legacy_occurrences.get(assignment.pk, {})
        scheduled_dates = set()
        current_date = start_date
        while current_date <= end_date:
            if current_date.weekday() in weekdays:
                scheduled_dates.add(current_date)
            current_date += timedelta(days=1)
        scheduled_dates.update(feedback)
        if assignment.completada_en and not feedback:
            scheduled_dates.add(assignment.fecha_programada)
            feedback[assignment.fecha_programada] = {
                'completed_at': assignment.completada_en,
                'pain': None,
                'difficulty': '',
                'comment': '',
            }
        OcurrenciaRutina.objects.using(connection.alias).bulk_create([
            OcurrenciaRutina(
                asignacion_id=assignment.pk,
                fecha=occurrence_date,
                completada_en=feedback.get(occurrence_date, {}).get('completed_at'),
                nivel_dolor=feedback.get(occurrence_date, {}).get('pain'),
                dificultad={
                    'moderada': 'adecuada',
                    'media': 'adecuada',
                    'medio': 'adecuada',
                    'fácil': 'facil',
                    'difícil': 'dificil',
                }.get(
                    feedback.get(occurrence_date, {}).get('difficulty', ''),
                    feedback.get(occurrence_date, {}).get('difficulty', ''),
                ),
                comentario=feedback.get(occurrence_date, {}).get('comment', ''),
            )
            for occurrence_date in sorted(scheduled_dates)
        ])


